inseridos = 0
atualizados = 0
for codigo, nome, cidade, estado, ultima_compra in CLIENTES:
    ex = con.execute('SELECT id FROM clientes WHERE codigo=?', (codigo,)).fetchone()
    if ex:
        con.execute('UPDATE clientes SET nome=?, cidade=?, estado=?, ultima_compra=? WHERE codigo=?',
                    (nome, cidade, estado, ultima_compra, codigo))
        atualizados += 1
    else:
        con.execute('INSERT INTO clientes (codigo, nome, cidade, estado, ultima_compra, ativo) VALUES (?,?,?,?,?,1)',
                    (codigo, nome, cidade, estado, ultima_compra))
        inseridos += 1
con.commit()
print(f'Clientes inseridos: {inseridos}, atualizados: {atualizados}')
total = con.execute('SELECT COUNT(*) FROM clientes').fetchone()[0]
print(f'Total de clientes no banco: {total}')
print('Concluido!')